package com.weeklyplan.partner;
import com.weeklyplan.project.Project; import jakarta.persistence.*; import java.io.Serializable;
@Entity @Table(name="partner_resource_projects") @IdClass(PartnerResourceProject.Key.class) public class PartnerResourceProject { @Id @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="resource_id") private PartnerResource resource; @Id @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="project_id") private Project project; @Column(name="cooperation_role") private String cooperationRole; @Column(columnDefinition="TEXT") private String note; public PartnerResource getResource(){return resource;} public Project getProject(){return project;} public String getCooperationRole(){return cooperationRole;} public String getNote(){return note;} public static PartnerResourceProject create(PartnerResource r,Project p,SavePartnerProjectRequest q){PartnerResourceProject x=new PartnerResourceProject();x.resource=r;x.project=p;x.cooperationRole=q.cooperationRole();x.note=q.note();return x;} public static class Key implements Serializable { private Long resource; private Long project; public boolean equals(Object o){if(this==o)return true;if(!(o instanceof Key k))return false;return java.util.Objects.equals(resource,k.resource)&&java.util.Objects.equals(project,k.project);} public int hashCode(){return java.util.Objects.hash(resource,project);} } }
